// Plugin de Figma que arma el diseño de «El Ahorcado Móvil»:
//   1. Wireframes de baja fidelidad (capas editables)
//   2. Mockups de alta fidelidad con el prototipo navegable ya conectado
//   3. Guía de estilos (colores, tipografía, estados de teclas, ícono y splash)
// Uso: Figma Desktop → Plugins → Development → Import plugin from manifest… → este manifest.json
// Archivo generado: las imágenes van al final en DATOS.

const ANCHO = 393;
const ALTO = 852;
const ESPACIO = 120;

function rgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
}
const solido = (hex, opacity = 1) => ({ type: 'SOLID', color: rgb(hex), opacity });

function texto(padre, contenido, x, y, { tamano = 16, estilo = 'Regular', color = '#1A1F2B' } = {}) {
  const t = figma.createText();
  padre.appendChild(t);
  t.fontName = { family: 'Inter', style: estilo };
  t.fontSize = tamano;
  t.characters = contenido;
  t.fills = [solido(color)];
  t.x = x;
  t.y = y;
  return t;
}

function marco(padre, nombre, x, y, ancho = ANCHO, alto = ALTO) {
  const f = figma.createFrame();
  padre.appendChild(f);
  f.name = nombre;
  f.resize(ancho, alto);
  f.x = x;
  f.y = y;
  return f;
}

function rellenoImagen(base64) {
  const imagen = figma.createImage(figma.base64Decode(base64));
  return [{ type: 'IMAGE', imageHash: imagen.hash, scaleMode: 'FILL' }];
}

// La primera página se reutiliza si el archivo está vacío; las demás se crean.
let paginaLibre = null;
async function nuevaPagina(nombre) {
  const pagina = paginaLibre || figma.createPage();
  paginaLibre = null;
  pagina.name = nombre;
  await figma.setCurrentPageAsync(pagina);
  return pagina;
}

// ---------- 1. Wireframes ----------
async function paginaWireframes() {
  const pagina = await nuevaPagina('1. Wireframes');
  texto(pagina, 'Wireframes de baja fidelidad', 0, -140, { tamano: 40, estilo: 'Bold' });
  DATOS.wireframes.forEach(([nombre, svg], i) => {
    const nodo = figma.createNodeFromSvg(svg);
    pagina.appendChild(nodo);
    nodo.name = nombre;
    nodo.x = (i % 5) * (ANCHO + ESPACIO);
    nodo.y = Math.floor(i / 5) * (ALTO + ESPACIO);
  });
  return pagina;
}

// ---------- 2. Mockups y prototipo ----------
const SUAVE = { type: 'EASE_OUT' };
const TRANSICIONES = {
  adelante: { type: 'PUSH', direction: 'LEFT', matchLayers: false, easing: SUAVE, duration: 0.3 },
  atras: { type: 'PUSH', direction: 'RIGHT', matchLayers: false, easing: SUAVE, duration: 0.3 },
  modal: { type: 'DISSOLVE', easing: SUAVE, duration: 0.25 },
};
const ir = (destino, transicion = 'adelante') => ({
  type: 'NODE',
  destinationId: destino.id,
  navigation: 'NAVIGATE',
  transition: TRANSICIONES[transicion],
  resetScrollPosition: true,
});
const VOLVER = { type: 'BACK' };

// Zona táctil invisible sobre un botón del mockup.
async function zona(pantalla, nombre, caja, accion) {
  const r = figma.createRectangle();
  pantalla.appendChild(r);
  r.name = `Zona · ${nombre}`;
  r.x = caja.x;
  r.y = caja.y;
  r.resize(caja.w, caja.h);
  r.fills = [solido('#FFFFFF', 0)];
  await r.setReactionsAsync([{ trigger: { type: 'ON_CLICK' }, actions: [accion] }]);
}

async function conectar(p) {
  const Z = DATOS.zonas;
  const atras = { x: 0, y: 8, w: 56, h: 48 }; // flecha ← del encabezado

  await p.splash.setReactionsAsync([
    { trigger: { type: 'AFTER_TIMEOUT', timeout: 1500 }, actions: [ir(p.inicio, 'modal')] },
    { trigger: { type: 'ON_CLICK' }, actions: [ir(p.inicio, 'modal')] },
  ]);

  await zona(p.inicio, 'Jugar', Z.inicio.jugar, ir(p.categoria));
  await zona(p.inicioError, 'Jugar', Z.inicio.jugar, ir(p.categoria));
  await zona(p.inicio, 'Instrucciones', Z.inicio.instrucciones, ir(p.instrucciones));
  await zona(p.inicio, 'Estadísticas', Z.inicio.estadisticas, ir(p.estadisticas));
  await zona(p.inicio, 'Configuración', Z.inicio.configuracion, ir(p.configuracion));
  for (const pantalla of [p.instrucciones, p.estadisticas, p.configuracion, p.categoria]) {
    await zona(pantalla, 'Atrás', atras, VOLVER);
  }
  await zona(p.categoria, 'Comenzar', Z.categoria.comenzar, ir(p.juego));

  // Recorrido de una partida: 3 vidas → 2 → 1 → fin del juego.
  const jugadas = [[p.juego, p.adivinada], [p.juego2, p.vidaPerdida], [p.juego3, p.vidaPerdida2], [p.juegoUltima, p.fin]];
  for (const [juego, resultado] of jugadas) {
    await zona(juego, 'Tocar una letra', Z.juego.teclado, ir(resultado, 'modal'));
    await zona(juego, 'Atrás', atras, ir(p.categoria, 'atras'));
  }
  await zona(p.adivinada, 'Siguiente palabra', Z.resultado.siguiente, ir(p.juego2, 'modal'));
  await zona(p.vidaPerdida, 'Siguiente palabra', Z.resultado.siguiente, ir(p.juego3, 'modal'));
  await zona(p.vidaPerdida2, 'Siguiente palabra', Z.resultado.siguiente, ir(p.juegoUltima, 'modal'));
  await zona(p.fin, 'Jugar de nuevo', Z.fin.jugarDeNuevo, ir(p.juego, 'modal'));
  await zona(p.adivinada, 'Menú', Z.resultado.menu, ir(p.inicio, 'atras'));
  await zona(p.vidaPerdida, 'Menú', Z.resultado.menu, ir(p.inicio, 'atras'));
  await zona(p.vidaPerdida2, 'Menú', Z.resultado.menu, ir(p.inicio, 'atras'));
  await zona(p.fin, 'Menú', Z.fin.menu, ir(p.inicio, 'atras'));
}

async function paginaMockups() {
  const pagina = await nuevaPagina('2. Mockups y prototipo');
  const filas = [
    ['Tema claro · recorrido del jugador (prototipo: presiona ▶ Present)',
      ['splash', 'inicio', 'categoria', 'juego', 'adivinada', 'juego2', 'vidaPerdida', 'juego3', 'vidaPerdida2', 'juegoUltima', 'fin']],
    ['Tema claro · otras pantallas y estados', ['inicioError', 'instrucciones', 'estadisticas', 'configuracion']],
    ['Tema oscuro', ['oscuroInicio', 'oscuroCategoria', 'oscuroJuego', 'oscuroConfiguracion']],
  ];
  const p = {};
  filas.forEach(([titulo, claves], fila) => {
    const y = fila * (ALTO + 260);
    texto(pagina, titulo, 0, y - 90, { tamano: 32, estilo: 'Bold' });
    claves.forEach((clave, i) => {
      const { nombre, png } = DATOS.mockups[clave];
      p[clave] = marco(pagina, nombre, i * (ANCHO + ESPACIO), y);
      p[clave].fills = rellenoImagen(png);
    });
  });
  await conectar(p);
  pagina.flowStartingPoints = [{ nodeId: p.splash.id, name: 'Recorrido del jugador' }];
  return pagina;
}

// ---------- 3. Guía de estilos ----------
function muestraColor(pagina, x, y, nombre, hex, grupo) {
  const r = figma.createRectangle();
  pagina.appendChild(r);
  r.x = x;
  r.y = y;
  r.resize(150, 100);
  r.cornerRadius = 12;
  r.fills = [solido(hex)];
  r.strokes = [solido('#D5DBE5')];
  r.strokeWeight = 1;
  texto(pagina, nombre, x, y + 108, { tamano: 14, estilo: 'Semi Bold' });
  texto(pagina, hex.toUpperCase(), x, y + 128, { tamano: 14, color: '#5B6475' });
  const estilo = figma.createPaintStyle();
  estilo.name = `${grupo}/${nombre}`;
  estilo.paints = [solido(hex)];
}

function caja(pagina, x, y, ancho, alto, fondo, borde, radio, etiqueta, colorTexto, tamano) {
  const f = marco(pagina, etiqueta, x, y, ancho, alto);
  f.cornerRadius = radio;
  f.fills = [solido(fondo)];
  f.strokes = [solido(borde)];
  f.strokeWeight = 1.5;
  const t = texto(f, etiqueta, 0, 0, { tamano, estilo: 'Bold', color: colorTexto });
  t.x = (ancho - t.width) / 2;
  t.y = (alto - t.height) / 2;
  return f;
}

async function paginaEstilos() {
  const pagina = await nuevaPagina('3. Guía de estilos');
  texto(pagina, 'Guía de estilos · El Ahorcado Móvil', 0, 0, { tamano: 40, estilo: 'Bold' });

  texto(pagina, 'Colores', 0, 90, { tamano: 28, estilo: 'Bold' });
  Object.entries(DATOS.temas).forEach(([tema, colores], columna) => {
    const x0 = columna * 900;
    const grupo = tema === 'claro' ? 'Tema claro' : 'Tema oscuro';
    texto(pagina, grupo, x0, 140, { tamano: 20, estilo: 'Semi Bold' });
    Object.entries(colores).forEach(([nombre, hex], i) => {
      muestraColor(pagina, x0 + (i % 5) * 170, 180 + Math.floor(i / 5) * 170, nombre, hex, grupo);
    });
  });

  texto(pagina, 'Tipografía (Inter en Figma · Roboto en Android)', 0, 720, { tamano: 28, estilo: 'Bold' });
  let y = 780;
  for (const [nombre, tamano, estilo] of DATOS.tipografia) {
    texto(pagina, `${nombre} · ${tamano} sp`, 0, y, { tamano, estilo });
    const t = figma.createTextStyle();
    t.name = nombre;
    t.fontName = { family: 'Inter', style: estilo };
    t.fontSize = tamano;
    y += tamano + 26;
  }

  texto(pagina, 'Estados de las teclas', 900, 720, { tamano: 28, estilo: 'Bold' });
  DATOS.teclas.forEach(([nombre, fondo, letra], i) => {
    caja(pagina, 900 + i * 130, 780, 50, 50, fondo, '#D5DBE5', 10, 'A', letra, 20);
    texto(pagina, nombre, 900 + i * 130, 840, { tamano: 14 });
  });
  texto(pagina, 'Área táctil mínima 48 × 48 dp · teclado de 4 filas de 7 (A–Z con Ñ)', 900, 880, { tamano: 14, color: '#5B6475' });

  texto(pagina, 'Botones', 900, 940, { tamano: 28, estilo: 'Bold' });
  caja(pagina, 900, 1000, 300, 52, '#2E74B5', '#2E74B5', 14, 'Primario', '#FFFFFF', 17);
  caja(pagina, 900, 1066, 300, 52, '#FFFFFF', '#D5DBE5', 14, 'Secundario', '#1A1F2B', 17);
  caja(pagina, 900, 1132, 300, 52, '#D64545', '#D64545', 14, 'Peligro', '#FFFFFF', 17);

  texto(pagina, 'Ícono y splash', 0, 1260, { tamano: 28, estilo: 'Bold' });
  const icono = figma.createRectangle();
  pagina.appendChild(icono);
  icono.name = 'Ícono de la app';
  icono.x = 0;
  icono.y = 1320;
  icono.resize(200, 200);
  icono.cornerRadius = 44;
  icono.fills = rellenoImagen(DATOS.icono);
  const splash = marco(pagina, 'Splash', 260, 1320, 196, 426);
  splash.cornerRadius = 24;
  splash.fills = [solido('#1F3864')];
  const logo = figma.createRectangle();
  splash.appendChild(logo);
  logo.x = 18;
  logo.y = 123;
  logo.resize(160, 160);
  logo.fills = rellenoImagen(DATOS.splash);
  return pagina;
}

async function main() {
  figma.notify('Creando wireframes, mockups y prototipo…', { timeout: 3000 });
  for (const style of ['Regular', 'Semi Bold', 'Bold']) await figma.loadFontAsync({ family: 'Inter', style });
  if (figma.root.children.length === 1 && figma.currentPage.children.length === 0) paginaLibre = figma.currentPage;

  await paginaWireframes();
  const mockups = await paginaMockups();
  await paginaEstilos();

  await figma.setCurrentPageAsync(mockups);
  figma.viewport.scrollAndZoomIntoView(mockups.children);
  figma.closePlugin('✅ Listo. Presiona ▶ Present en «2. Mockups y prototipo» para probar el prototipo.');
}

